"""Later validators over depot run outputs.

Same form as validators.py: each validator vN(items) -> (passed, measured).
An empty input never passes.
"""

# Inclusive bounds for a supplier's reliability score (assumed; see notes).
RELIABILITY_MIN = 0
RELIABILITY_MAX = 100


def v7(entries):
    """Every warehouse's max_units <= capacity. measured: offending warehouse names."""
    entries = list(entries)
    if not entries:
        return False, []
    bad = [e["wh"] for e in entries if e["max_units"] > e["capacity"]]
    return (not bad), bad


def _unnotified(entry):
    """Expiries in the entry that have no matching notification (multiset-aware)."""
    notified = [tuple(n) for n in entry["notified"]]
    missing = []
    for exp in entry["expired"]:
        key = tuple(exp)
        if key in notified:
            notified.remove(key)
        else:
            missing.append(list(exp))
    return missing


def v8(entries):
    """Every expiry has a notification. measured: expiries [sku, wh, qty] not notified."""
    entries = list(entries)
    if not entries:
        return False, []
    bad = []
    for e in entries:
        bad.extend(_unnotified(e))
    return (not bad), bad


def v9(entries):
    """Every reliability within [RELIABILITY_MIN, RELIABILITY_MAX]. measured: offending suppliers."""
    entries = list(entries)
    if not entries:
        return False, []
    bad = [e["supplier"] for e in entries
           if not (RELIABILITY_MIN <= e["reliability"] <= RELIABILITY_MAX)]
    return (not bad), bad
