import unittest

from validators_later import v7, v8, v9


class TestV7(unittest.TestCase):
    def test_empty_fails(self):
        self.assertEqual(v7([]), (False, []))

    def test_pass(self):
        self.assertEqual(v7([{"wh": "A", "capacity": 10, "max_units": 10}]), (True, []))

    def test_fail(self):
        rows = [{"wh": "A", "capacity": 10, "max_units": 11},
                {"wh": "B", "capacity": 5, "max_units": 1}]
        self.assertEqual(v7(rows), (False, ["A"]))


class TestV8(unittest.TestCase):
    def test_empty_fails(self):
        self.assertEqual(v8([]), (False, []))

    def test_pass(self):
        e = {"expired": [["s", "w", 1]], "notified": [["s", "w", 1]]}
        self.assertEqual(v8([e]), (True, []))

    def test_missing(self):
        e = {"expired": [["s", "w", 1], ["t", "w", 2]], "notified": [["s", "w", 1]]}
        self.assertEqual(v8([e]), (False, [["t", "w", 2]]))

    def test_duplicate_needs_two_notifications(self):
        e = {"expired": [["s", "w", 1], ["s", "w", 1]], "notified": [["s", "w", 1]]}
        self.assertEqual(v8([e]), (False, [["s", "w", 1]]))


class TestV9(unittest.TestCase):
    def test_empty_fails(self):
        self.assertEqual(v9([]), (False, []))

    def test_pass_bounds(self):
        rows = [{"supplier": "a", "reliability": 0}, {"supplier": "b", "reliability": 100}]
        self.assertEqual(v9(rows), (True, []))

    def test_fail(self):
        rows = [{"supplier": "a", "reliability": -1}, {"supplier": "b", "reliability": 101},
                {"supplier": "c", "reliability": 50}]
        self.assertEqual(v9(rows), (False, ["a", "b"]))


if __name__ == "__main__":
    unittest.main()
